HEADS = {3: 'El defensor de la cristiandad', 4: 'La batalla de Lepanto', 8: 'La Armada de 1588', 11: 'El coste de las guerras'}


def extend(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(text='Un rey que gobierna desde Madrid\nFelipe II gobernó como un rey autoritario pero «nacional»: mantuvo las instituciones heredadas de su padre y la autonomía de sus reinos, y puso a España, y sobre todo a Castilla, en el centro del imperio. En 1561 trasladó la corte a Madrid, que fue desde entonces capital permanente (en esa misma época empezó a construirse El Escorial, {{fig:escorial}}) salvo el breve intervalo vallisoletano de 1601 a 1606. Apenas visitó los territorios de fuera de la Península y los administró por medio de oficiales y virreyes; los administrativos solían tener estudios universitarios, sobre todo de Alcalá y Salamanca. La fuente inglesa matiza la imagen de rey absoluto: el imperio era una unión personal de reinos que defendían celosamente sus derechos, y la palabra del rey era a menudo menos eficaz que la de las asambleas y los señores locales.',
        quotes=[Q('es_felipe2','En 1561, Felipe II decidió trasladar la sede de la corte y convirtió a Madrid en la primera capital permanente de la monarquía española'), Q('es_felipe2','Felipe II no visitó apenas sus territorios de fuera de la península y los administró a través de oficiales y virreyes'), Q('en_felipe2','The Spanish Empire was not a single monarchy with one legal system but a personal union of separate realms')]))
    P.append(dict(text='El príncipe Carlos y 1568. Don Carlos, nacido en 1545 de la primera esposa de Felipe, María de Portugal, que murió en el parto, tenía una salud débil y un desequilibrio mental que la fuente atribuye a una probable consanguinidad: tenía cuatro bisabuelos en lugar de ocho. Conspiró con los rebeldes flamencos, fue detenido por su padre, procesado y encerrado, y murió en 1568 en el Alcázar de Madrid, donde estaba recluido. Ese mismo año murió la reina Isabel de Valois y Felipe se encontró a los cuarenta y un años viudo y sin hijo varón, con rebeliones en los Países Bajos y las Alpujarras, el avance de la herejía en Francia y el resurgir de la amenaza otomana. Fue, según la fuente, uno de los peores años de su vida.',
        quotes=[Q('es_felipe2','Caracterizado por su desequilibrio mental, de muy posible origen genético, pues tenía cuatro bisabuelos (en lugar de los ocho naturales)'), Q('es_felipe2','Conspiró con poco disimulo con los rebeldes flamencos contra su padre'), Q('es_felipe2','Este fue uno de los peores años para Felipe II'), Q('en_felipe2','Philip II also grappled with the problem of the large Morisco population')]))
    P.append(dict(text='La rebelión de las Alpujarras\nLa pragmática sanción de 1 de enero de 1567 prohibía las costumbres de los moriscos granadinos, desde la lengua y los vestidos hasta los baños y las ceremonias. Había sido propuesta por un sínodo de obispos del reino de Granada, que decidió abandonar la política de persuasión por la de represión, y aplicaba medidas que Carlos I había dejado en suspenso a cambio de 80 000 ducados. Los moriscos intentaron negociar, pero el rey se mostró inflexible. La rebelión ({{fig:alpujarras-mapa}}) estalló en diciembre de 1568 bajo el mando de Aben Humeya y duró hasta marzo de 1571, y tuvo un carácter violento, con la muerte de sacerdotes y la profanación de iglesias, en la que desempeñaron un papel importante los monfíes.',
        quotes=[Q('es_alpujarras','Estos acordaron cambiar la política de persuasión'), Q('es_alpujarras','Felipe II dio finalmente su aprobación y el resultado fue la pragmática de 1 de enero de 1567'), Q('en_alpujarras','starting in December 1568 and lasting till March 1571'), Q('en_alpujarras','the torturing and murder of priests and sacristans, and the destruction and profanation of churches')]))
    P.append(dict(text='Una guerra de religión y de deportación. Las dos fuentes coinciden en el desenlace: vencidos los sublevados, los moriscos supervivientes fueron deportados a distintos puntos de Castilla, y las poblaciones del reino de Granada se repoblaron con colonos cristianos de otras partes del país. En Castilla la población morisca pasó de veinte mil a cien mil personas; miles fueron vendidos como esclavos y en la Córdoba de 1573 había unos mil quinientos esclavos moriscos. La rebelión es una clave para entender la posterior expulsión general de 1609, que se estudia en el capítulo sobre los Austrias del siglo XVII.',
        quotes=[Q('es_alpujarras','cuya población morisca pasó de veinte mil a cien mil personas'), Q('es_alpujarras','En la Córdoba de 1573 había unos mil quinientos esclavos moriscos'), Q('en_alpujarras','Most of the Morisco population was then expelled from the Kingdom of Granada and was dispersed throughout the Kingdom of Castille'), Q('en_alpujarras','Catholic settlers were brought in from other parts of the country to repopulate them')]))
    P.append(dict(text='La revuelta de los Países Bajos\nFelipe heredó los Países Bajos de su padre, y para ellos eran a la vez un punto estratégico y una debilidad: Amberes era el puerto más importante del norte de Europa y un centro de comercio de la lana castellana, pero a diferencia de Castilla o Aragón, los Países Bajos no formaban parte de la herencia de los Reyes Católicos y veían a Felipe como un rey extranjero que nunca vivía allí y delegaba su gobierno. A ello se sumaba el choque religioso: Felipe quería aplicar los acuerdos tridentinos y las autoridades civiles se mostraban reacias a ejecutar las penas de los inquisidores. La fuente inglesa suma el descontento por los impuestos y la persecución incesante de los protestantes.',
        quotes=[Q('es_felipe2','los Países Bajos no eran parte de la herencia de los Reyes Católicos, y veían a España como un país extranjero'), Q('es_felipe2','El rey quería aplicar los acuerdos tridentinos'), Q('en_felipe2','There was discontent in the Netherlands about Philip\'s taxation demands and the incessant persecution of Protestants.')]))
    P.append(dict(text='De los mendigos a la represión de Alba. El 5 de abril de 1566 la baja nobleza se concentró en Bruselas ante la gobernadora, Margarita de Parma, y fue despreciada como «mendigos», nombre que adoptaron después. En el verano, predicadores protestantes provocaron los disturbios anticlericales de la Furia Iconoclasta. El 29 de octubre de 1566 el rey reunió a sus consejeros y optó por la fuerza, enviando al duque de Alba, cuya represión fue durísima: Egmont y Horn fueron ejecutados en 1568. La fuente inglesa añade que hubo matanzas de civiles en Malinas, Naarden, Zutphen y Haarlem, y que Alba presumía de haber quemado o ejecutado a 18 600 personas, una cifra que debe tomarse con la cautela que merece una fuente de parte.',
        quotes=[Q('es_felipe2','La baja nobleza se concentró en Bruselas el 5 de abril de 1566'), Q('es_felipe2','el monarca optó por la fuerza'), Q('en_felipe2','In 1568, Alba had Lamoral, Count of Egmont and Philip de Montmorency, Count of Horn executed in Brussels\' central square'), Q('en_felipe2','Alba boasted that he had burned or executed 18,600 persons in the Netherlands')]))
    P.append(dict(text='Farnesio, Utrecht y la abjuración. Después de Alba, Felipe buscó soluciones con Requesens, Juan de Austria y Alejandro Farnesio, que consiguió el sometimiento de las provincias católicas del sur en la Unión de Arras; los protestantes del norte formaron la Unión de Utrecht (1579) y el 26 de julio de 1581 declararon en el acta de abjuración que ya no reconocían a Felipe como rey. En 1576 la falta de pagas a los soldados provocó el saqueo de Amberes, la llamada «furia española». Felipe no renunció a esos territorios y Farnesio recuperó gran parte, pero cedió la soberanía de las provincias a su hija Isabel Clara Eugenia y al archiduque Alberto por el Acta de Cesión del 6 de mayo de 1598. La guerra terminaría en 1648, con el reconocimiento de la República holandesa.',
        quotes=[Q('es_felipe2','Alejandro Farnesio, que consiguió el sometimiento de las provincias católicas del sur en la Unión de Arras'), Q('es_felipe2','El 26 de julio de 1581'), Q('en_felipe2','Rampant inflation and the loss of treasure fleets from the New World prevented Philip from paying his soldiers consistently, leading to the so-called Spanish Fury at Antwerp in 1576'), Q('en_felipe2','The war came to an end in 1648, when the Dutch Republic was recognised by the Spanish Crown as independent.')]))
    P.append(dict(text='La crisis sucesoria portuguesa\nEn 1578 murió Sebastián I de Portugal en la batalla de Alcazarquivir sin dejar heredero y le sucedió su tío abuelo, el cardenal Enrique, que murió sin hijos dos años después. Entre los candidatos estaban Felipe II (hijo de Isabel de Portugal), la duquesa de Braganza y el prior de Crato, hijo ilegítimo. Felipe se adelantó a la decisión de las Cortes e invadió el reino; las tropas del duque de Alba derrotaron al prior en Alcántara ({{fig:alcantara-1580}}), y las Cortes de Tomar reconocieron a Felipe como rey en 1581. La fuente inglesa precisa que Felipe fue coronado Felipe I de Portugal el 17 de julio de 1580 y que la batalla de Alcántara dejó 4000 portugueses muertos, heridos o capturados frente a 500 bajas españolas.',
        quotes=[Q('es_portugal1580','En 1578, el joven rey Sebastián I de Portugal moría en la batalla de Alcazarquivir sin dejar heredero'), Q('es_portugal1580','Antes de la elección, Felipe II de España se anticipó a la decisión'), Q('en_felipe2','In 1580, Philip II marched into Portugal and defeated Prior António\'s troops in the Battle of Alcântara.'), Q('en_felipe2','crowned Philip I of Portugal on 17 July 1580')]))
    P.append(dict(role='definition', text='Unión Ibérica: unión dinástica de Portugal con los demás reinos hispánicos bajo un mismo monarca, desde 1580 hasta 1640, en la que cada reino conservaba sus propias leyes e instituciones.',
        quotes=[Q('es_portugal1580','una unión dinástica aeque principaliter'), Q('en_felipe2','a near sixty-year personal union under the rule of the Philippine Dynasty began')]))
    P.append(dict(text='Portugal bajo los Austrias. Con la corona, Felipe obtuvo el extenso imperio portugués. Al marchar a Madrid en 1583 nombró virrey en Lisboa a su sobrino Alberto de Austria y creó en Madrid un Consejo de Portugal que le asesorara en los asuntos portugueses. Para Castilla la anexión fue, sin embargo, un esfuerzo económico: pasó a costear la defensa marítima de un imperio extenso sin que Portugal aportara a la hacienda común. La unión duró hasta 1640, cuando comenzó la guerra de Restauración portuguesa, que se estudia en el capítulo sobre 1640.',
        quotes=[Q('en_felipe2','When Philip left for Madrid in 1583, he made his nephew Albert of Austria his viceroy in Lisbon.'), Q('es_felipe2','La anexión de Portugal fue económicamente un gran esfuerzo para Castilla'), Q('es_portugal1580','Esta unión ibérica se prolongó hasta 1640')]))
    P.append(dict(text='Las finanzas de la Corona\nLa Hacienda real se declaró en bancarrota tres veces según la fuente española (1557, 1575 y 1596) y cuatro según la inglesa (1557, 1560, 1575 y 1596), una discrepancia que muestra que el recuento depende de qué suspensión de pagos se considere una bancarrota. Tampoco coinciden en la deuda heredada: unos veinte millones de ducados según una, unos treinta y seis según la otra. En 1575 la interrupción de la ruta lanera por la guerra de Flandes provocó una recesión y una segunda suspensión de pagos. En 1577 el «Remedio General» consolidó la deuda a largo plazo mediante juros con un interés del 7 %, avalados por los metales americanos. Los banqueros genoveses adelantaban el dinero a un precio muy alto para Castilla.',
        quotes=[Q('es_felipe2','Durante su reinado, la Hacienda Real se declaró en bancarrota tres veces (1557, 1575 y 1596)'), Q('en_felipe2','This debt caused Philip II to default on loans in 1557, 1560, 1575, and 1596'), Q('en_felipe2','Charles V had left his son Philip with a debt of about 36 million ducats'), Q('es_felipe2','Esto se conoce como «el Remedio General» de 1577')]))
    P.append(dict(text='Impuestos y crisis. Los ingresos de la Corona se cuadruplicaron durante el reinado porque se cuadruplicó la carga fiscal sobre Castilla y porque la riqueza de América alcanzó valores históricos; los ingresos americanos suponían entre el 10 % y el 20 % anual. Felipe subió impuestos antiguos como la alcabala, la cruzada, el subsidio y las tercias reales, e implantó otros como el excusado en 1567. En 1590 las Cortes aprobaron los «millones», ocho millones de ducados pagaderos en seis años (la fuente española los presenta como anuales, pero la cifra se refiere al total), para la nueva Armada y la política militar, lo que según la fuente arruinó a las ciudades castellanas. La fuente inglesa añade el límite estructural: España tenía una población escasa y la recaudación se arrendaba en buena parte a los señores locales.',
        quotes=[Q('es_felipe2','pues la carga fiscal sobre Castilla se cuadruplicó y la riqueza procedente de América alcanzó valores históricos'), Q('es_felipe2','En 1590 se aprueban en las Cortes los millones'), Q('en_felipe2','Philip faced major difficulties in raising taxes, and the collection was largely farmed out to local lords.')]))
    P.append(dict(text='Antonio Pérez y Aragón\nAntonio Pérez fue secretario de cámara y del Consejo de Estado de Felipe II, hijo del secretario de Carlos V Gonzalo Pérez; fue nombrado secretario de Estado en 1567 y durante diez años tuvo una gran influencia sobre el rey. Jugó con las tensas relaciones de Felipe con su hermano Juan de Austria y fue acusado del asesinato de Juan de Escobedo, secretario de este, en 1578. Juzgado, usó su ascendencia aragonesa para acogerse a la protección del Justicia Mayor de Aragón y huyó a Francia. Los aragoneses se sublevaron para defender sus fueros y el Justicia, Juan de Lanuza, fue ejecutado por orden del rey; la fuente española sitúa esta crisis en 1590-1591 y la inglesa habla de noviembre de 1592, otra discrepancia de fechas. El caso muestra que los fueros eran un límite real al poder regio y que el rey estaba dispuesto a vencerlos por la fuerza.',
        quotes=[Q('es_aperez','fue el secretario de cámara y del Consejo de Estado del rey de España Felipe II'), Q('es_aperez','para acogerse a la protección del Justicia Mayor de Aragón'), Q('en_aperez','He was said to have organised the murder of Juan de Escobedo.'), Q('en_felipe2','the Attorney General (Justicia) of the kingdom, Juan de Lanuza, was executed on Philip II\'s orders'), Q('es_felipe2','La crisis de Aragón (1590 a 1591) y Antonio Pérez')]))
    P.append(dict(text='¿Una España desgastada por su imperio?\nLa mayoría de historiadores coincide, según la fuente española, en que la pobreza en que quedó el país al final del reinado está directamente relacionada con la carga del imperio y con su papel de defensor de la cristiandad. Durante el reinado apenas hubo un respiro militar: al final tuvo tres frentes simultáneos, Países Bajos, Inglaterra y Francia, y los diputados de las últimas Cortes pidieron una retirada de los ejércitos de Flandes. En 1598 firmó la paz con Francia; con Flandes no logró un acuerdo. Es un balance discutido: la fuente inglesa subraya a la vez el florecimiento de la cultura española, con el comienzo del Siglo de Oro, y la fragilidad de la hacienda.',
        quotes=[Q('es_felipe2','La mayoría de historiadores coincide en subrayar que la situación de pobreza'), Q('es_felipe2','Al final de su reinado contaba con tres frentes simultáneos: los Países Bajos, Inglaterra y Francia'), Q('en_felipe2','Spanish culture flourished during Philip\'s reign, beginning the "Spanish Golden Age"')]))
    return P


