                dict(label='Causas religiosas y fiscales', points=[dict(text='El rey quiso aplicar los acuerdos tridentinos y persiguió a los protestantes; además, los impuestos suscitaron descontento.', quotes=[Q('es_felipe2','El rey quería aplicar los acuerdos tridentinos'), Q('en_felipe2','There was discontent in the Netherlands about Philip\'s taxation demands and the incessant persecution of Protestants.')])]),
                dict(label='Por qué se prolongó', points=[dict(text='Alba optó por la represión; la falta de pagas provocó motines; la hacienda de Felipe se hundía mientras la economía holandesa crecía, y los frentes se multiplicaron.', quotes=[Q('es_felipe2','el monarca optó por la fuerza'), Q('en_felipe2','The Dutch gained an advantage over the Spanish because of their growing economic strength, in contrast to Philip\'s burgeoning economic troubles.')])]),
